using System.Linq;using UnityEngine;using UnityEditor;
public static class InspectMuckNative {public static string Run(){AssetDatabase.Refresh();return string.Join("\n",new[]{"Gronk","Chief","Guardian"}.Select(n=>{var p=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Research/MuckNative/GameObject/"+n+".prefab");return n+" animators="+string.Join(",",p.GetComponentsInChildren<Animator>(true).Select(a=>a.name))+" skins="+string.Join(",",p.GetComponentsInChildren<SkinnedMeshRenderer>(true).Select(r=>r.name+":"+r.sharedMesh.name))+" materials="+string.Join(",",p.GetComponentsInChildren<Renderer>(true).SelectMany(r=>r.sharedMaterials).Where(m=>m).Select(m=>m.name).Distinct());}));}}
